def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    scale = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = None
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif g == 18:
            q = 0.0
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        if q is not None:
            total += x * q
            scale += x * abs(q)
    return total / scale if scale > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        r = (p.get(e) or {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r * r * r
            weight += x
    return 4.0 * pi * total / (3.0 * weight * v) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                nearest[i] = min(nearest[i], d / (ri + rj))
    total = 0.0
    weight = 0.0
    for i in range(n):
        if nearest[i] < inf and occ[i] > 0:
            total += occ[i] * nearest[i]
            weight += occ[i]
    return total / weight if weight > 0 else 0.0

