def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    props = [p.get(a.get('element')) or {} for a in sites]
    en = [a.get('eneg') for a in props]
    radii = [a.get('covalent_radius_A') for a in props]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            ri = radii[i]
            rj = radii[j]
            if en[i] is not None and en[j] is not None and ri is not None and rj is not None and ri > 0 and rj > 0:
                r = d / (ri + rj)
                if r <= 2.0:
                    total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 * exp(-2.0 * (r - 1.0)) / d
    return total / (2.0 * weight * v)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    chi = [0.0] * n
    invh = [0.0] * n
    numerator = 0.0
    denominator = 0.0
    for i in range(n):
        a = p.get(sites[i].get('element')) or {}
        ie = a.get('first_ionization_energy_eV')
        ea = a.get('electron_affinity_eV')
        if ie is not None and ea is not None and ie > 0:
            chi[i] = 0.5 * (ie + ea)
            invh[i] = 1.0 / max(ie - ea, 0.5)
            numerator += occ[i] * chi[i] * invh[i]
            denominator += occ[i] * invh[i]
    if denominator <= 0:
        return 0.0
    level = numerator / denominator
    q = [(level - chi[i]) * invh[i] for i in range(n)]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            total += occ[i] * occ[j] * q[i] * q[j] * exp(-d / 3.0) / d
    return total / (2.0 * weight)

def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    entries = []
    for e, x in (s.get('composition') or {}).items():
        if x is not None and x > 0:
            a = p.get(e) or {}
            entries.append((e, a.get('first_ionization_energy_eV'), a.get('electron_affinity_eV')))
    best = inf
    for e, ie, ea in entries:
        if ie is None:
            continue
        for f, fie, fea in entries:
            if e != f and fea is not None:
                best = min(best, ie - fea)
    return best if best < inf else 0.0

def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    donor = 0.0
    acceptor = 0.0
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        weight += x
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = 0.0
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        donor += x * max(q, 0.0)
        acceptor += x * max(-q, 0.0)
    return min(donor, acceptor) / weight if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    q = [0.0] * n
    for i in range(n):
        a = p.get(sites[i].get('element')) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        if g == 1 or g == 2:
            q[i] = float(g)
        elif g == 13:
            q[i] = 3.0
        elif g == 14:
            q[i] = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q[i] = float(g - 18)
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q[i] = min(max(v, 0.0), 3.0)
    edges = s.get('neighbors') or []
    near = [inf] * n
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and q[i] > 0 and q[j] < 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    denominators = [0.0] * n
    contacts = []
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and q[i] > 0 and q[j] < 0 and near[i] < inf:
            r = d / near[i]
            if r < 2.0 and occ[j] > 0:
                w = exp(1.0 - r ** 6)
                denominators[i] += occ[j] * w
                contacts.append((i, j, w))
    supply = [0.0] * n
    for i, j, w in contacts:
        if denominators[i] > 0:
            supply[j] += occ[i] * q[i] * w / denominators[i]
    weight = sum(occ[i] for i in range(n) if q[i] < 0)
    if weight <= 0:
        return 0.0
    error = sum(occ[i] * (supply[i] + q[i]) ** 2 for i in range(n) if q[i] < 0)
    return sqrt(max(error / weight, 0.0))
